from itertools import product

def is_kawaii(sequence):
    """
    Checks if a sequence of positive integers is kawaii.
    Kawaii condition: for each k >= 2, if k appears, then k-1 appears, 
    and the first occurrence of k-1 comes before the last occurrence of k.
    """
    L = len(sequence)

    # 1. Identify the set of elements present
    elements_present = sorted(list(set(sequence)))

    if not elements_present:
        return False # Should not happen for L=5

    M_actual = elements_present[-1]

    # 2. Check the dependency chain (k appears => k-1 appears)
    # Since we only use {1, 2, 3}, we check for k=2 and k=3.

    for k in range(2, M_actual + 1):
        if k in elements_present:
            if (k - 1) not in elements_present:
                # This case should not happen if we only generate sequences using {1, 2, 3}
                # and M_actual is the max, but it's a safety check.
                return False

    # 3. Check the ordering constraint: F(k-1) < L(k)
    for k in range(2, M_actual + 1):
        if k in elements_present:

            # Find F(k-1): first index (0-based) of k-1
            try:
                first_k_minus_1 = sequence.index(k - 1)
            except ValueError:
                # Should not happen based on check #2, but handled just in case
                return False

            # Find L(k): last index (0-based) of k
            # We iterate backwards to find the last occurrence
            last_k = -1
            for i in range(L - 1, -1, -1):
                if sequence[i] == k:
                    last_k = i
                    break

            # Check the condition: first_k_minus_1 < last_k
            if first_k_minus_1 >= last_k:
                return False

    return True

