def is_kawaii(sequence, allowed_elements):
    N = len(sequence)

    # 1. Check element dependency (k appears => k-1 appears)
    M = max(sequence) if sequence else 0
    if M == 0:
        return True # Empty sequence

    for k in range(2, M + 1):
        if k in sequence:
            if k - 1 not in sequence:
                return False

    # 2. Check positional constraints: L_{k-1} < R_k for k=2 to M

    def find_positions(seq, element):
        indices = [i for i, x in enumerate(seq) if x == element]
        if not indices:
            # Should not happen if condition 1 passed for M > 1
            return -1, -1 
        return indices[0], indices[-1]

    for k in range(2, M + 1):
        # Get L_{k-1} (First occurrence of k-1)
        L_km1 = find_positions(sequence, k - 1)[0]

        # Get R_k (Last occurrence of k)
        R_k = find_positions(sequence, k)[1]

        # Check constraint
        if L_km1 >= R_k:
            return False

    return True

