def is_kawaii(sequence):
    """Checks if a sequence is kawaii based on the definition."""
    N = len(sequence)
    # 1. Identify all unique elements M_set
    M_set = set(sequence)
    if not M_set:
        return False

    M = max(M_set)

    # 2. Check Element Dependency (k implies k-1 present)
    for k in range(2, M + 1):
        if k in M_set and (k - 1) not in M_set:
            return False

    # 3. Check Positional Constraint L_{k-1} < R_k

    # Find first (L) and last (R) occurrences for all elements present
    first_occurrence = {}
    last_occurrence = {}

    for i, element in enumerate(sequence):
        index = i + 1 # 1-based indexing
        if element not in first_occurrence:
            first_occurrence[element] = index
        last_occurrence[element] = index

    # Check constraint L_{k-1} < R_k for k=2 to M
    for k in range(2, M + 1):
        if k in M_set and (k - 1) in M_set:
            L_k_minus_1 = first_occurrence[k - 1]
            R_k = last_occurrence[k]

            if L_k_minus_1 >= R_k:
                return False

    return True

def count_kawaii_sequences(N, M):
    """Counts kawaii sequences of length N using elements {1, ..., M}."""
    from itertools import product

    elements = list(range(1, M + 1))
    count = 0

    # Iterate over all M^N possible sequences
    for sequence_tuple in product(elements, repeat=N):
        sequence = list(sequence_tuple)

        if is_kawaii(sequence):
            count += 1

    return count

